// План specs/job-date-label.md 1.1–1.4 (кейсы JD-01…JD-04). Admin, компания «test». Только просмотр, формы не сохраняем,
// в Job Details ничего не вводим (автосохранение).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import { setLanguage } from '../admin-plans/plans-helpers';
import { LABEL, Lang, VIEW_JOB, expectDateLabel, expectNoScheduledDate, openCompletedRow } from './date-label-helpers';

test.use({ storageState: ADMIN_STATE });

for (const lang of ['en', 'he'] as Lang[]) {
  const L = lang.toUpperCase();

  test.describe(`Подпись «Date» вместо «Scheduled Date» (#6d5cda04) ${L}`, () => {
    test.beforeEach(async ({ page }) => {
      await setLanguage(page, lang);
    });

    test(`New Job (${L}): field is labelled "${LABEL[lang].dateLine}", no "Scheduled Date" #6d5cda04 @desktop @prod-safe`, async ({ page }) => {
      await page.goto('/JobForm?action=new');
      await expectDateLabel(page, lang, 'New Job');
      await expectNoScheduledDate(page.locator('main'), 'New Job');
    });

    test(`New Lead (${L}): field is labelled "${LABEL[lang].dateLine}", no "Scheduled Date" #6d5cda04 @desktop @prod-safe`, async ({ page }) => {
      await page.goto('/CreateLead');
      await expectDateLabel(page, lang, 'New Lead');
      await expectNoScheduledDate(page.locator('main'), 'New Lead');
    });

    test(`Job Details (${L}): Schedule & Assignment field is labelled "${LABEL[lang].dateLine}", no "Scheduled Date" #6d5cda04 @desktop @prod-safe`, async ({ page }) => {
      const row = await openCompletedRow(page, lang, VIEW_JOB);
      await row.getByText(VIEW_JOB, { exact: true }).click();
      await page.waitForURL(/\/JobDetail\?id=/);
      await expect(page.getByText(`#${VIEW_JOB}`).first()).toBeVisible();
      await expectDateLabel(page, lang, 'Job Details');
      await expectNoScheduledDate(page.locator('main'), 'Job Details');
    });

    test(`Job Preview (${L}): date line is "${LABEL[lang].dateLine}", no "Scheduled Date" #6d5cda04 @desktop @prod-safe`, async ({ page }) => {
      const row = await openCompletedRow(page, lang, VIEW_JOB);
      await row.getByTitle(LABEL[lang].preview).click();
      const dialog = page.getByRole('dialog').last();
      await expect(dialog).toContainText(VIEW_JOB);
      const lines = (await dialog.innerText()).split('\n').map((l) => l.trim());
      expect(lines, `превью ${VIEW_JOB}: строка «${LABEL[lang].dateLine}»`).toContain(LABEL[lang].dateLine);
      await expectNoScheduledDate(dialog, 'Job Preview');
    });

    test(`New Job on Android (${L}): field is labelled "${LABEL[lang].dateLine}", no "Scheduled Date" #6d5cda04 @android @prod-safe`, async ({ page }) => {
      await page.goto('/JobForm?action=new');
      await expectDateLabel(page, lang, 'New Job (Pixel 7)');
      await expectNoScheduledDate(page.locator('main'), 'New Job (Pixel 7)');
    });
  });
}
